from taf.ul.kpi_selector.utilities.kpi_logger import log_input_and_output
from taf.ul.kpi_selector.utilities.exceptions import MissingObjectError

scorpio_sws = ["urm6", "erm6"]
amber_master_sws = ["trm6", "srm6", "lrm6", "mmimo_srm6"]
chile_sws = ["chb0"]
gen4_5g = ["5gh4, 5ga4", "5ge4"]
pulsar = ["5gb4", "5gd4"]
gen3_LF = ["5ll3", "5gl3"]
default = ["default_flag"]
megatron = ["ctb6"]
galvatron = ["cta6"]
maverick = ["fru6"]
zodiac = ["frm6"]


class Restrictions:
    def __init__(self, bts):
        self.bts = bts

    @log_input_and_output
    def use_restrictions_from_OM_GEN_SFS_PERF_CAP_13441(self, init_ru_id=None, admin_ru_id=None):
        """
        Adds extra 2 min 30 sec in scorpio, amber, pulsar and master radios. In 5g 4gen radios it is recommended to set
        0x40025 = 1 flag in RU swconfig to get equivalent performance. Adds extra 3 mins for chile radios and 2 mins
        for Megatron and Galvatron family radios.
        Adds 60 sec to KPI per every 9 cells in configuration (+30 sec in chile radio case).
        """
        scm_flags = self._get_scm_flags(init_ru_id=init_ru_id, admin_ru_id=admin_ru_id)

        additional_time = 0

        if any((scm_flag.lower() in default for scm_flag in scm_flags)):
            additional_time += 240

        elif any((scm_flag.lower() in chile_sws for scm_flag in scm_flags)):
            additional_time += 180

        elif any(
            (
                any((scm_flag.lower() in amber_master_sws for scm_flag in scm_flags)),
                any((scm_flag.lower() in scorpio_sws for scm_flag in scm_flags)),
                any((scm_flag.lower() in pulsar for scm_flag in scm_flags)),
            )
        ):
            additional_time += 150

        elif any(
                (
                    any((scm_flag.lower() in megatron for scm_flag in scm_flags)),
                    any((scm_flag.lower() in galvatron for scm_flag in scm_flags)),
                )
        ):
            additional_time += 120

        return self._add_time_according_to_cells_and_setup_mode(number_of_cells=self.bts.number_of_cells,
                                                                scm_flags=scm_flags,
                                                                additional_time=additional_time)

    @log_input_and_output
    def use_restrictions_from_OM_GEN_SFS_PERF_CAP_13258(self, cell_dist_name=None):
        """
        Adds extra 40 sec for chile and Gen3 LF radios.
        For pulsar, master, amber, scorpio, maverick and AEQN radios adds extra 10 sec.
        For Galvatron and Megatron radios adds extra 20s.
        If beamforming vector transfer is active adds extra 20s.
        :param cell_dist_name: dist name of cell for which restrictions should be used
        :type cell_dist_name: str
        """
        scm_flags = self._get_scm_flags_depending_on_distname(cell_dist_name)
        additional_time = 0

        if any(
            (
                any((scm_flag.lower() in chile_sws for scm_flag in scm_flags)),
                any((scm_flag.lower() in gen3_LF for scm_flag in scm_flags)),
                any((scm_flag.lower() in default for scm_flag in scm_flags))
            )
        ):
            additional_time += 40

        elif any(
            (
                any((scm_flag.lower() in megatron for scm_flag in scm_flags)),
                any((scm_flag.lower() in galvatron for scm_flag in scm_flags)),
            )
        ):
            additional_time += 20

        elif any(
            (
                any((scm_flag.lower() in amber_master_sws for scm_flag in scm_flags)),
                any((scm_flag.lower() in scorpio_sws for scm_flag in scm_flags)),
                any((scm_flag.lower() in pulsar for scm_flag in scm_flags)),
                any((scm_flag.lower() in maverick for scm_flag in scm_flags)),
                "AEQN" in self.bts.rmod_hw_types,
            )
        ):
            additional_time += 10

        if cell_dist_name:
            cell = self._get_cell_via_distname(cell_dist_name)
            if cell.is_beamforming_vector_transfer_active:
                additional_time += 20

        return additional_time

    @log_input_and_output
    def use_restrictions_from_OM_GEN_SFS_PERF_CAP_10517(self):
        """
        Adds extra 4 min for master, amber, pulsar, scorpio and AEQN radios.
        For chile radios adds extra 8 minutes.
        For megatron, galvatron, zodiac, maverick adds extra 2 minutes.
        Extends timeout by 90 sec in case of setup mode different than SA.
        """
        additional_time = 0
        scm_flags = self._get_scm_flags_from_dict()

        if any(
            (
                any((scm_flag.lower() in chile_sws for scm_flag in scm_flags)),
                any((scm_flag.lower() in default for scm_flag in scm_flags))
            )
        ):
            additional_time += 480

        elif any(
            (
                any((scm_flag.lower() in amber_master_sws for scm_flag in scm_flags)),
                any((scm_flag.lower() in scorpio_sws for scm_flag in scm_flags)),
                any((scm_flag.lower() in pulsar for scm_flag in scm_flags)),
                "AEQN" in self.bts.rmod_hw_types,
            )
        ):
            additional_time += 240

        elif any(
                (
                    any((scm_flag.lower() in megatron for scm_flag in scm_flags)),
                    any((scm_flag.lower() in galvatron for scm_flag in scm_flags)),
                    any((scm_flag.lower() in zodiac for scm_flag in scm_flags)),
                    any((scm_flag.lower() in maverick for scm_flag in scm_flags)),
                )
        ):
            additional_time += 120

        if self.bts.setup_mode != "SA":
            additional_time += 90

        return additional_time

    @log_input_and_output  # noqa: C901
    def use_additional_time_for_reset_rf(self, init_ru_id, admin_ru_id, stream="after 21A"):  # noqa: C901
        """
        Adds additional 150s in case of amber and master radios.
        In case of chile radios adds 180s. If stream is newer than 21A adds 180s for scorpio RUs.
        Extends timeout by 30s in case of AEQN radio.
        :param init_ru_id: id for ru from init
        :type init_ru_id: str
        :param admin_ru_id: id for ru from api
        :type admin_ru_id: str
        :param stream: stream - enough specification is whether is stream newer than 21A.
        :type stream: str
        """
        if init_ru_id or admin_ru_id:
            scm_flags, rmod_type = self._get_scm_flags_for_ru(
                init_rmod_id=init_ru_id, admin_rmod_id=admin_ru_id, return_rmod_type=True
            )

        else:
            scm_flags = self._get_scm_flags_from_dict()
            rmod_type = self.bts.rmod_hw_types

        additional_time = 0

        if any((scm_flag.lower() in amber_master_sws for scm_flag in scm_flags)):
            additional_time += 150

        if stream != '21A' and any((scm_flag.lower() in scorpio_sws for scm_flag in scm_flags)):
            additional_time += 150

        if any((scm_flag.lower() in chile_sws for scm_flag in scm_flags)):
            additional_time += 180

        if any((scm_flag.lower() in default for scm_flag in scm_flags)):
            additional_time += 180

        if "AEQN" in rmod_type:
            additional_time += 30

        if self.bts.rf_sharing:
            additional_time += 30

        return additional_time

    @log_input_and_output
    def use_restrictions_from_OM_GEN_SFS_PERF_CAP_12847(self):
        """
        Adds extra 4 min for master, amber, pulsar, scorpio, chile and AEQN radios.
        For megatron, galvatron, zodiac, maverick adds extra 2 minutes.
        """
        additional_time = 0
        scm_flags = self._get_scm_flags_from_dict()

        if any(
            (
                any((scm_flag.lower() in chile_sws for scm_flag in scm_flags)),
                any((scm_flag.lower() in default for scm_flag in scm_flags)),
                any((scm_flag.lower() in amber_master_sws for scm_flag in scm_flags)),
                any((scm_flag.lower() in scorpio_sws for scm_flag in scm_flags)),
                any((scm_flag.lower() in pulsar for scm_flag in scm_flags)),
                "AEQN" in self.bts.rmod_hw_types,
            )
        ):
            additional_time += 240

        elif any(
            (
                any((scm_flag.lower() in megatron for scm_flag in scm_flags)),
                any((scm_flag.lower() in galvatron for scm_flag in scm_flags)),
                any((scm_flag.lower() in zodiac for scm_flag in scm_flags)),
                any((scm_flag.lower() in maverick for scm_flag in scm_flags)),
            )
        ):
            additional_time += 120

        return additional_time

    @log_input_and_output
    def should_use_cu_reset_via_restrictions_OM_GEN_SFS_PERF_CAP_10515(self, rat):
        """
        Returns True if reset cu kpi should be used instead of lte/nr rat resets, False otherwise.
        Cu kpi should be used for lte and nr rats if bbmod of type: "ABIO", "ABIN", "ABIP", "ABIQ", "ABIC", "ABIL",
        "ASOE", "ASOF", "ASOG", "ASOH" is present on testline
        :param rat: type of rat, e.g. "nr"
        :type rat: str
        """
        if rat in ["lte", "nr"]:
            for bbmod in self.bts.bbmod_hw_types:
                if bbmod in ["ABIO", "ABIN", "ABIP", "ABIQ", "ABIC", "ABIL", "ASOE", "ASOF", "ASOG", "ASOH"]:
                    return True
        return False

    @log_input_and_output
    def get_extra_time_from_restrictions_OM_GEN_SFS_PERF_CAP_10515(self, rat):
        """
        Gets extra time if graceful_cell_shutdown is enabled for lte and nr rats
        :param rat: type of rat, e.g. "nr"
        :type rat: str
        """
        if rat in ["lte", "nr"]:
            if self.bts.is_graceful_cell_shutdown_enabled:
                return 60
        return 0

    @log_input_and_output
    def use_restrictions_from_OM_GEN_SFS_PERF_CAP_19432(self):
        """
        Gets extra time if graceful_cell_shutdown is enabled or if setup_mode is NSA
        """
        extra_time = 0
        if self.bts.setup_mode == "NSA":
            extra_time += 240
        if self.bts.is_graceful_cell_shutdown_enabled:
            extra_time += 60
        return extra_time

    @log_input_and_output
    def get_additional_time_depending_on_cell_type(self, cell_dist_name):
        """
        Returns additional time for GSM cell
        :param cell_dist_name:  dist_name of the cell, which KPI cell block timeout will be applied to
        :type cell_dist_name: str
        :return: additional time in seconds
        :rtype: int
        """
        if cell_dist_name:
            cell = self._get_cell_via_distname(cell_dist_name)
            if cell.type == 'gsm':
                return 120
        return 0

    @log_input_and_output
    def _get_cell_via_distname(self, distname):
        for cell in self.bts.cells:
            if str(cell.id) == distname.split('-')[-1]:
                return cell
        raise MissingObjectError("Could not find cell object for cell distname: {}".format(distname))

    @log_input_and_output
    def _get_scm_flags_from_dict(self, rmod_type=None):
        if rmod_type:
            return [scm_flag for ru_dict in self.bts.rmod_scm_flags
                    for ru_type, scm_flag in ru_dict.items() if ru_type == rmod_type]

        else:
            return [scm_flag for ru_dict in self.bts.rmod_scm_flags
                    for ru_type, scm_flag in ru_dict.items()]

    @log_input_and_output
    def _get_scm_flags_for_ru(self, init_rmod_id, admin_rmod_id, return_rmod_type=False):
        rmod_type = self._get_rmod_type_by_init_id(init_rmod_id) if init_rmod_id else \
            self._get_rmod_type_by_admin_id(admin_rmod_id)
        scm_flags = self._get_scm_flags_from_dict(rmod_type=rmod_type)

        return (scm_flags, rmod_type) if return_rmod_type else scm_flags

    @log_input_and_output
    def _get_rmod_type_by_init_id(self, init_rmod_id):
        for rmod in self.bts.rmods:
            if rmod.init_id == init_rmod_id:
                return rmod.radio_type
        raise MissingObjectError("Could not find rmod with init rmod id: {}".format(init_rmod_id))

    @log_input_and_output
    def _get_rmod_type_by_admin_id(self, admin_rmod_id):
        for rmod in self.bts.rmods:
            if rmod.id == admin_rmod_id:
                return rmod.radio_type
        raise MissingObjectError("Could not find rmod with admin rmod id: {}".format(admin_rmod_id))

    @log_input_and_output
    def _get_scm_flags(self, init_ru_id, admin_ru_id):
        if init_ru_id is not None or admin_ru_id is not None:
            return self._get_scm_flags_for_ru(init_rmod_id=init_ru_id, admin_rmod_id=admin_ru_id)

        return self._get_scm_flags_from_dict()

    @log_input_and_output
    def _get_scm_flags_depending_on_distname(self, cell_dist_name):
        scm_flags = []
        if cell_dist_name:
            cell = self._get_cell_via_distname(cell_dist_name)
            for rmod in cell.parent_rmods:
                scm_flags.append(rmod.scm_flag)
        else:
            scm_flags = self._get_scm_flags_from_dict()

        return scm_flags

    @log_input_and_output
    def _add_time_according_to_cells_and_setup_mode(self, number_of_cells, scm_flags, additional_time):

        while number_of_cells > 4:
            if chile_sws[0] in scm_flags:
                additional_time += 30
            additional_time += 60
            number_of_cells -= 8

        return additional_time + 90 if self.bts.setup_mode != "SA" else additional_time
